const root=document.getElementById('app');
let selectedDate=null,selectedSlot=null,selectionSaved=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function poster(a){return `<div class="poster" style="--bg:${a.bg};--ink:${a.ink}" aria-hidden="true"><div class="poster-inner"><div class="poster-lines"></div><div class="poster-top"><span>APPLIED AI STUDIO</span><span class="poster-number">${String(apps.indexOf(a)+1).padStart(2,'0')}</span></div><div class="poster-title"${a.id==='hr-studio'?' style="font-size:25px"':''}>${a.title}</div><div class="poster-subtitle">${a.tagline}</div><div class="poster-shape"></div><div class="poster-symbol">${a.symbol}</div></div><div class="poster-strip"><span>✦</span> ${a.label}</div></div>`}
function catalog(){document.title='Explore applications | MCCIA AI Studio';root.innerHTML=`<div class="container"><div class="intro"><div><div class="eyebrow">MCCIA APPLIED AI STUDIO</div><h1>Small business. Meet big possibilities.</h1><p>Discover practical AI applications built for the way you work.</p></div><div class="collection-count"><b>10 applications</b> to explore</div></div><div class="grid">${apps.map(a=>`<a class="card" href="#/apps/${a.id}" aria-label="View ${a.name} details">${poster(a)}<h2>${a.name}</h2><p class="category">${a.category}</p><p>${a.tagline}</p></a>`).join('')}</div><div class="catalog-note"><span class="note-icon" aria-hidden="true">✧</span><div><strong>Find the right AI application for your business.</strong><p>Explore an application to see what it does, who it’s for, and choose a session with the studio.</p></div></div></div>`}
function detail(a){document.title=`${a.name} | MCCIA AI Studio`;root.innerHTML=`<div class="container" style="padding-top:20px;padding-bottom:0"><div class="breadcrumb"><a href="#/">Applications</a><span>/</span><span>${a.name}</span></div></div><section class="detail-hero" style="--hero-accent:${a.ink}"><div class="hero-inner"><div class="detail-poster">${poster(a)}</div><div class="detail-copy"><div class="eyebrow">${a.category}</div><h1>${a.name}</h1><p class="detail-tagline">${a.tagline}</p><div class="audience-box"><small>BUILT FOR</small><strong>${a.audience}</strong></div><p class="detail-meta">AI-powered &nbsp; · &nbsp; Built for MSMEs &nbsp; · &nbsp; MCCIA, Pune</p><a href="#/apps/${a.id}/book" class="primary">Book here <span aria-hidden="true">→</span></a></div></div></section><div class="container detail-body"><section><h2>About the application</h2><p>${a.description}</p><h2 style="margin-top:32px">What you can do</h2><ul class="features">${a.features.map(f=>`<li><span class="check" aria-hidden="true">✓</span>${f}</li>`).join('')}</ul></section><aside class="side-note"><div class="eyebrow">LET’S MAKE AI WORK FOR YOU</div><h3>Build it for your business</h3><p>Book a one-hour app-development session for ${a.name} with MCCIA Applied AI Studio.</p></aside></div>`}
function availableDays(){const result=[];const today=new Date(Date.now()+19800000);today.setUTCHours(0,0,0,0);for(let i=0;result.length<15;i++){const d=new Date(+today+i*86400000);if(d.getUTCDay()!==0&&d.getUTCDay()!==6)result.push(d.toISOString().slice(0,10));}return result;}
const times=['11:00','12:00','14:30','15:30'];
const timeLabels={'11:00':'11:00 AM – 12:00 PM','12:00':'12:00 PM – 1:00 PM','14:30':'2:30 PM – 3:30 PM','15:30':'3:30 PM – 4:30 PM'};
let availability=null,loadingSlots=false,bookingError='',receipt=null,bookingBusy=false,loadCounter=0;
let contact={name:'',email:'',company:''};
const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kolkata'});
function booking(a){document.title=`Book ${a.name} | MCCIA AI Studio`;const days=availableDays();root.innerHTML=`<div class="container"><a class="back" href="#/apps/${a.id}">← Back to ${a.name}</a><div class="booking-header"><div class="eyebrow">APP DEVELOPMENT · ONE HOUR</div><h1>Make time for smarter work.</h1><p>Book an app-development slot for ${a.name}.</p></div>${receipt?`<section class="success-panel"><div class="success-icon">✓</div><h1>Your development slot is booked.</h1><p><strong>${a.name}</strong><br>${dateLabel(receipt.date)}<br>${timeLabels[receipt.slot]} IST</p><p>Booking reference: <strong>${esc(receipt.id.slice(0,8).toUpperCase())}</strong></p><p>Keep this reference for your records. For changes, contact<br><a href="mailto:aistudio@mcciapune.com">aistudio@mcciapune.com</a> · <a href="tel:+918855885290">8855885290</a>.</p><a class="primary" href="#/">Explore applications</a></section>`:`<div class="booking-layout"><section class="booking-panel"><h2>1. Select a day</h2><p>Monday–Friday · All times in India Standard Time (IST).</p><div class="dates">${days.map(d=>{const day=new Date(d+'T12:00:00Z');return `<button class="date ${selectedDate===d?'selected':''}" data-day="${d}" aria-pressed="${selectedDate===d}" aria-label="${dateLabel(d)}" ${bookingBusy?'disabled':''}><span>${day.toLocaleDateString('en-IN',{weekday:'short',timeZone:'Asia/Kolkata'}).toUpperCase()}</span><strong>${day.getUTCDate()}</strong><span>${day.toLocaleDateString('en-IN',{month:'short',timeZone:'Asia/Kolkata'}).toUpperCase()}</span></button>`}).join('')}</div><h2>2. Select a time</h2><p class="availability-status" role="status">${loadingSlots?'Checking availability…':selectedDate?'One hour, dedicated to your application.':'Choose a day to see available slots.'}</p><div class="slots">${times.map(t=>`<button class="slot ${selectedSlot===t?'selected':''}" data-time="${t}" ${bookingBusy||loadingSlots||!availability?.find(s=>s.time===t)?.available?'disabled':''} aria-pressed="${selectedSlot===t}">${timeLabels[t]}</button>`).join('')}</div><div class="slot-legend"><span>Available</span><span>Unavailable</span></div><h2 style="margin-top:32px">3. Your details</h2><form id="booking-form"><div class="form-grid"><label>Full name <input name="name" autocomplete="name" required minlength="2" maxlength="100" value="${esc(contact.name)}" placeholder="Your full name" ${bookingBusy?'disabled':''}></label><label>Email address <input name="email" type="email" autocomplete="email" required maxlength="254" value="${esc(contact.email)}" placeholder="you@company.com" ${bookingBusy?'disabled':''}></label><label class="full-width">Company <span>(optional)</span><input name="company" autocomplete="organization" maxlength="150" value="${esc(contact.company)}" placeholder="Your company name" ${bookingBusy?'disabled':''}></label></div></form><p class="form-note">Your details will be saved with your booking so the studio can identify your reservation.</p></section><aside class="summary"><h2>Your development session</h2><div class="summary-app"><span class="mini-icon" style="--bg:${a.bg};--ink:${a.ink}" aria-hidden="true">${a.symbol}</span><div><strong>${a.name}</strong><small>${a.category}</small></div></div><dl><dt>Date</dt><dd>${selectedDate?dateLabel(selectedDate):'Choose a day'}</dd><dt>Time</dt><dd>${selectedSlot?timeLabels[selectedSlot]+' IST':'Choose a time'}</dd><dt>Duration</dt><dd>1 hour</dd><dt>Hosted by</dt><dd>MCCIA Applied AI Studio</dd></dl>${bookingError?`<div class="error" role="alert">${esc(bookingError)} <button id="retry-availability" type="button">Refresh availability</button></div>`:''}<button form="booking-form" type="submit" class="primary" ${!selectedSlot||bookingBusy?'disabled':''}>${bookingBusy?'Booking your slot…':'Confirm booking'}</button><p class="fine">One reservation per studio time slot. Your booking is confirmed once it has been saved.</p></aside></div>`}</div>`;
 if(receipt)return;
 root.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>loadDay(a,b.dataset.day));
 root.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{selectedSlot=b.dataset.time;bookingError='';booking(a);root.querySelector(`[data-time="${selectedSlot}"]`).focus()});
 root.querySelectorAll('input').forEach(input=>input.oninput=()=>contact[input.name]=input.value);
 root.querySelector('#retry-availability')?.addEventListener('click',()=>{if(selectedDate)loadDay(a,selectedDate)});
 root.querySelector('#booking-form').onsubmit=async e=>{e.preventDefault();if(!selectedSlot||bookingBusy)return;bookingBusy=true;bookingError='';booking(a);try{const response=await fetch('/api/bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({appId:a.id,date:selectedDate,slot:selectedSlot,...contact})});const result=await response.json();if(!response.ok){if(response.status===409){selectedSlot=null;await loadDay(a,selectedDate)}throw new Error(result.error||'Unable to save your booking.')}receipt=result;contact={name:'',email:'',company:''}}catch(error){bookingError=error.message||'Could not connect. Please try again.'}finally{bookingBusy=false;booking(a);if(receipt)window.scrollTo(0,0)}};
}
async function loadDay(a,date){const requestId=++loadCounter;selectedDate=date;selectedSlot=null;availability=null;loadingSlots=true;bookingError='';booking(a);try{const r=await fetch('/api/availability?date='+date);const result=await r.json();if(!r.ok)throw new Error(result.error||'Unable to load availability.');if(requestId===loadCounter)availability=result.slots;}catch(e){if(requestId===loadCounter)bookingError='Availability could not be loaded. Please refresh to try again.'}finally{if(requestId===loadCounter&&location.hash===`#/apps/${a.id}/book`){loadingSlots=false;booking(a);root.querySelector(`[data-day="${date}"]`)?.focus()}}}
function render(){loadCounter++;selectedDate=null;selectedSlot=null;receipt=null;availability=null;loadingSlots=false;bookingError='';const parts=location.hash.slice(1).split('/').filter(Boolean);if(!parts.length)catalog();else{const a=apps.find(a=>a.id===parts[1]);if(parts[0]==='apps'&&a&&parts.length<=3&&(!parts[2]||parts[2]==='book'))parts[2]==='book'?booking(a):detail(a);else{document.title='Page not found | MCCIA AI Studio';root.innerHTML='<div class="container empty"><h1>Application not found</h1><a class="primary" href="#/">Explore applications</a></div>'}}window.scrollTo(0,0)}
window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_app_booking',title:'Open app development booking',description:'Open the booking screen for an application. Does not reserve a slot.',inputSchema:{type:'object',properties:{appId:{type:'string',enum:apps.map(a=>a.id)}},required:['appId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async({appId})=>{if(!apps.some(a=>a.id===appId))throw new Error('Unknown application');history.replaceState(null,'',`#/apps/${appId}/book`);render();return {appId,stage:'select_date_and_time',booked:false}}})).catch(()=>{});}catch{}}
